<template>
	<view class="zuti">

		<rich-text :nodes="content"></rich-text>

	</view>
</template>
<script>
	import {
		loaded,
		loading,
		toast,
		redirectTo,
		navigateTo
	} from '@/utils/index.js';
	import {
		img_PATH
	} from '@/config';
	import {
		getUserAgreement
	} from '@/api/index.js'
	export default {
		data() {
			return {
				imgurl: img_PATH,
				CustomBar: this.CustomBar,
				showLoading: false,
				showNone: false,
				content: ''
			};
		},

		components: {

		},
		onLoad() {

		},
		created() {
			this.init()
		},
		// 触底的事件
		onReachBottom() {

		},
		methods: {
			async init() {
				let _data = await getUserAgreement();
				if (_data.code == 200) {
					this.content = _data.data.content
				}
			},
			to(path) {
				navigateTo(path)
			},
		},

	}
</script>

<style scoped lang="scss">
	.zuti {
		min-height: 100vh;
		width: 100%;
		padding: 30rpx 25rpx;

	}
</style>